use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut pairs: Vec<(i64, i64)> = input
        .as_array()
        .unwrap()
        .iter()
        .map(|pair| {
            let arr = pair.as_array().unwrap();
            (arr[0].as_i64().unwrap(), arr[1].as_i64().unwrap())
        })
        .collect();

    pairs.sort_by(|a, b| {
        a.0.cmp(&b.0).reverse().then_with(|| a.1.cmp(&b.1))
    });

    let sorted_ids: Vec<i64> = pairs.into_iter().map(|(_, id)| id).collect();
    serde_json::Value::Array(sorted_ids.into_iter().map(serde_json::Value::from).collect())
}
